        "code": ".mobile-block {\r\n  display: none;\r\n}\r\n\r\n@media (max-width: 1200px) {\r\n  /* tablet devices */\r\n}\r\n@media (max-width: 992px) {\r\n  /* small tablet devices */\r\n  .slider-main .item-slide {\r\n    height: auto;\r\n  }\r\n\r\n  .table-shopping-cart tr td:first-child {\r\n    width: 250px;\r\n  }\r\n  .table-shopping-cart .itemside .info {\r\n    padding: 0;\r\n  }\r\n  .table-shopping-cart .itemside .aside {\r\n    display: none;\r\n  }\r\n}\r\n@media all and (max-width: 768px) {\r\n  /* mobile devices */\r\n  .mobile-block {\r\n    display: block;\r\n  }\r\n\r\n  .mobile-hide {\r\n    display: none;\r\n  }\r\n\r\n  .section-header .logo {\r\n    max-height: 40px;\r\n    width: auto;\r\n  }\r\n  .section-header .header-main .brand-wrap {\r\n    margin-bottom: 1rem;\r\n    display: inline-block;\r\n  }\r\n  .section-header .header-main .search {\r\n    margin-bottom: 1rem;\r\n  }\r\n\r\n  .item-feature {\r\n    margin-bottom: 20px;\r\n  }\r\n\r\n  .mobile-order-first {\r\n    order: -1;\r\n  }\r\n\r\n  .mobile-order-1 {\r\n    order: 1;\r\n  }\r\n\r\n  .mobile-order-2 {\r\n    order: 2;\r\n  }\r\n\r\n  .mobile-order-3 {\r\n    order: 3;\r\n  }\r\n\r\n  .mobile-py {\r\n    padding-top: 20px;\r\n    padding-bottom: 20px;\r\n  }\r\n\r\n  .mobile-pb {\r\n    padding-bottom: 20px;\r\n  }\r\n\r\n  .mobile-pt {\r\n    padding-top: 20px;\r\n  }\r\n\r\n  .navbar-expand .navbar-collapse {\r\n    flex-direction: column;\r\n  }\r\n}\r\n\r\n/*# sourceMappingURL=responsive.css.map */",
