        "file": "orders/urls.py",
        "code": "from django.urls import path\r\nfrom . import views\r\n\r\n\r\nurlpatterns = [  \r\n    path('place_order/', views.place_order, name='place_order'),\r\n    path('payments/', views.payments, name='payments'),\r\n    path('order_complete/', views.order_complete, name='order_complete'),\r\n]",
