        "title": "forgot_password.html",
        "description": "Código-fonte: `templates/accounts/forgot_password.html`",
        "file": "templates/accounts/forgot_password.html",
        "code": "{% extends 'base.html' %}\r\n\r\n{% block content %}\r\n\r\n\t<!-- Main Section Start -->\r\n    <div class=\"main-section\">\r\n        <div class=\"page-section nopadding cs-nomargin\" style=\"margin-top: 0px;padding-top: 60px;padding-bottom: 60px;margin-bottom: 0px;\">\r\n            <div class=\"container\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-lg-12 col-md-12 col-sm-12 col-xs-12 \">\r\n                        <div class=\"user-dashboard loader-holder\" style=\"width: 450px; min-height: auto;\">\r\n                            <div class=\"user-holder\">\r\n                        <h4 class=\"text-center\" style=\"margin-bottom: 0;\">Forgot your Password?</h4>\r\n                        <p class=\"text-center\">Please enter your email address and we will send you a link to reset your password.</p>\r\n                        <hr>\r\n                        <div id=\"restaurant-sets-holder\">\r\n                            <form class=\"form-fields-set foodbakery-dev-restaurant-form\" method=\"post\" action=\"{% url 'forgot_password' %}\" enctype=\"multipart/form-data\">\r\n                                {% csrf_token %}\r\n                                <ul class=\"register-add-restaurant-tab-container restaurant-information-tab-container\">\r\n                                    <li>\r\n                                        <div class=\"row\">\r\n                                            <div class=\"col-lg-12 col-md-12 col-sm-12 col-xs-12\">\r\n                                                <div class=\"row\">\r\n                                                    <div class=\"col-lg-12 col-md-12 col-sm-12 col-xs-12\">\r\n                                                        <div class=\"field-holder\">\r\n                                                            <label>Email Address</label>\r\n                                                            <input type=\"email\" name=\"email\" placeholder=\"Enter your email address\">\r\n                                                        </div>\r\n                                                    </div>                                                   \r\n                                                </div>\r\n                                            </div>\r\n                                        </div>\r\n                                    </li>\r\n                                    <li>\r\n                                        <div class=\"row\">\r\n                                            <div class=\"col-lg-12 col-md-12 col-sm-12 col-xs-12\">\r\n                                                <div class=\"field-holder\">\r\n                                                    <div class=\"payment-holder text-center\">\r\n                                                        <input type=\"submit\" value=\"Continue\" id=\"btn-next-restaurant-information\" class=\"bgcolor\">\r\n                                                    </div>\r\n                                                </div>\r\n                                            </div>\r\n                                            <div class=\"row\">\r\n                                                <div class=\"col-lg-12 col-md-12 col-sm-12 col-xs-12\">\r\n                                                   {% include 'includes/alerts.html' %}\r\n                                                </div>\r\n                                            </div>\r\n                                        </div>                                \r\n                                    </li>\r\n                                </ul>\r\n                            </form>\r\n                        </div>\r\n                    </div>\r\n                    </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <!-- Main Section End -->\r\n\r\n{% endblock %}",
