        "description": "Código-fonte: `templates/accounts/registerVendor.html`",
        "file": "templates/accounts/registerVendor.html",
        "code": "{% extends 'base.html' %}\r\n\r\n{% block content %}\r\n\r\n\t<!-- Main Section Start -->\r\n<div class=\"main-section\">\r\n    <div class=\"page-section nopadding cs-nomargin\" style=\"margin-top: 0px;padding-top: 60px;padding-bottom: 60px;margin-bottom: 0px;\">\r\n        <div class=\"container\">\r\n            <div class=\"row\">\r\n                <div class=\"col-lg-12 col-md-12 col-sm-12 col-xs-12 \">\r\n                    <div class=\"user-dashboard loader-holder\">\r\n                        <div class=\"user-holder\">\r\n                    <h4 class=\"text-center\" style=\"margin-bottom: 0;\">PARTNER WITH FOODONLINE</h4>\r\n                    <p class=\"text-center\">Register your restaurant with foodOnline marketplace and get more customer.</p>\r\n                    <hr>\r\n                    <div id=\"restaurant-sets-holder\">\r\n                        <form class=\"form-fields-set foodbakery-dev-restaurant-form\" method=\"post\" action=\"{% url 'registerVendor' %}\" enctype=\"multipart/form-data\">\r\n                            {% csrf_token %}\r\n                            <ul class=\"register-add-restaurant-tab-container restaurant-information-tab-container\">\r\n                                <li>\r\n                                    <div class=\"row\">\r\n                                        <div class=\"col-lg-12 col-md-12 col-sm-12 col-xs-12\">\r\n                                            <div class=\"row\">\r\n                                                <ul >\r\n                                                    <li>\r\n                                                        <div class=\"col-lg-6 col-md-6 col-sm-6 col-xs-12\">\r\n                                                            <div class=\"field-holder\">\r\n                                                                <label>First Name</label>{{form.first_name}}\r\n                                                            </div>\r\n                                                        </div>\r\n                                                        <div class=\"col-lg-6 col-md-6 col-sm-6 col-xs-12\">\r\n                                                            <div class=\"field-holder\">\r\n                                                                <label>Last Name</label>{{form.last_name}}\r\n                                                            </div>\r\n                                                        </div>\r\n                                                        <div class=\"col-lg-6 col-md-6 col-sm-6 col-xs-12\">\r\n                                                            <div class=\"field-holder\">\r\n                                                                <label>Restaurant Name</label>{{v_form.vendor_name}}\r\n                                                            </div>\r\n                                                        </div>         \r\n                                                        <div class=\"col-lg-6 col-md-6 col-sm-6 col-xs-12\">\r\n                                                            <div class=\"field-holder\">\r\n                                                                <label>Restaurant License</label>{{v_form.vendor_license}}\r\n                                                            </div>\r\n                                                        </div>                                                                \r\n                                                        <div class=\"col-lg-6 col-md-6 col-sm-6 col-xs-12\">\r\n                                                            <div class=\"field-holder\">\r\n                                                                <label>Email Address</label>{{form.email}}\r\n                                                            </div>\r\n                                                        </div>\r\n                                                        <div class=\"col-lg-6 col-md-6 col-sm-6 col-xs-12\">\r\n                                                            <div class=\"field-holder\">\r\n                                                                <label>Username</label>{{form.username}}\r\n                                                            </div>\r\n                                                        </div>\r\n                                                    </li>\r\n                                                    \r\n                                                    <li>\r\n                                                        <div class=\"col-lg-6 col-md-6 col-sm-12 col-xs-12\">\r\n                                                            <div class=\"field-holder\">\r\n                                                                <label>Password</label>\r\n                                                                {{form.password}}\r\n                                                            </div>\r\n                                                        </div>\r\n                                                        <div class=\"col-lg-6 col-md-6 col-sm-12 col-xs-12\">\r\n                                                            <div class=\"field-holder\">\r\n                                                                <label>Confirm Password</label>\r\n                                                                {{form.confirm_password}}\r\n                                                            </div>\r\n                                                        </div>\r\n                                                    </li>\r\n                                                </ul>\r\n                                            </div>\r\n                                        </div>\r\n                                    </div>\r\n                                </li>\r\n                                <li>\r\n                                    <ul class=\"errorlist\">\r\n                                        {% for field in form%}\r\n                                            {% if field.errors %}\r\n                                                {%  for error in field.errors %}\r\n                                                    <li style=\"color: red;\">{{error}}</li>\r\n                                                {% endfor %}\r\n                                            {% endif %}\r\n                                        {% endfor %}\r\n                                        <li style=\"color: red;\">{{form.non_field_errors}}</li>\r\n                                    </ul>\r\n                                    <div class=\"row\">\r\n                                        <div class=\"col-lg-12 col-md-12 col-sm-12 col-xs-12\">\r\n                                            <div class=\"field-holder\">\r\n                                                <div class=\"payment-holder\">\r\n                                                    <input type=\"submit\" value=\"REGISTER\" id=\"btn-next-restaurant-information\" class=\"bgcolor\">\r\n                                                </div>\r\n                                            </div>\r\n                                  \n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
        "implementation": [
          "path: templates/accounts/registerVendor.html",
          "GitHub: https://github.com/CanonEngineer/FoodOnlineDjango/blob/main/templates/accounts/registerVendor.html"
        ]
