        "title": "place_order.html",
        "description": "Código-fonte: `templates/orders/place_order.html`",
        "file": "templates/orders/place_order.html",
        "code": "{% extends 'base.html' %}\r\n{% load static %}\r\n\r\n{% block content %}\r\n\r\n<!-- Main Section Start -->\r\n<div class=\"main-section pt-5\">    \r\n    <div class=\"page-section\">\r\n        <div class=\"container\">\r\n            <div class=\"row\">                \r\n                <div class=\"col-lg-7 col-md-7 col-sm-7 col-xs-12\">\r\n                    <div class=\"tabs-holder horizontal\">\r\n                        <ul class=\"stickynav-tabs nav nav-tabs\">\r\n                            <li class=\"active\"><a data-toggle=\"tab\" href=\"#home\"><i class=\"fa fa-shopping-cart text-danger\"></i>Review Your Billing Address</a></li>                            \r\n                        </ul>\r\n                        <div class=\"tab-content\">\r\n                            <div id=\"home\" class=\"tab-pane in active\">\r\n                                <div class=\"menu-itam-holder\">  \r\n                                    <div id=\"menu-item-list-6272\" class=\"menu-itam-list\">  \r\n                                        <div class=\"billing-address\">\r\n                                            <div><b>{{ order.name }}</b></div>\r\n                                            <div><b>{{ order.address }}</b></div>\r\n                                            <div><b>{{ order.city }} - {{ order.pin_code }}</b></div>\r\n                                            <div><b>{{ order.state }}, {{ order.country }}</b></div>\r\n                                            <div><b>Phone: {{ order.phone }}</b></div>\r\n                                            <div><b>Email: {{ order.email }}</b></div>\r\n                                            <div><b>Payment: {{ order.payment_method }}</b></div>\r\n                                            <br>\r\n                                            <div><a href=\"{% url 'checkout' %}\" class=\"btn btn-outline-danger\">Edit</a></div>\r\n                                            <br>\r\n                                        </div>                                        \r\n                                    </div>                                    \r\n                                </div>\r\n                            </div>                            \r\n                        </div>\r\n                    </div>\r\n                </div> \r\n                <!--Your order section-->\r\n                <div class=\"col-lg-5 col-md-5 col-sm-5 col-xs-12\">\r\n                    <div class=\"tabs-holder horizontal\">\r\n                        <ul class=\"stickynav-tabs nav nav-tabs\">\r\n                            <li class=\"active\"><a data-toggle=\"tab\" href=\"#home\"><i class=\"icon- icon-room_service\"></i>Your Order</a></li>                            \r\n                        </ul>\r\n                        <div class=\"tab-content\">\r\n                            <div id=\"home\" class=\"tab-pane in active\">\r\n                                <div class=\"menu-itam-holder\">  \r\n                                    \r\n                                    <div>\r\n                                        <table class=\"table\">\r\n                                            <tbody>\r\n                                                {% for item in cart_items %}\r\n                                                <tr>\r\n                                                    <td><img src=\"{{ item.fooditem.image.url }}\" width=\"40\" alt=\"Food Image\"></td>\r\n                                                    <td><b>{{ item.fooditem }}</b></td>\r\n                                                    <td>{{ item.quantity }}</td>\r\n                                                    <td>$ {{ item.fooditem.price }}</td>\r\n                                                </tr>\r\n                                                {% endfor %}\r\n                                            </tbody>\r\n                                        </table>\r\n                                        <ul>\r\n                                            <li style=\"list-style-type: none;\">\r\n                                                Subtotal\r\n                                                <span class=\"price float-right\">\r\n                                                    <span class=\"currency\">$</span>\r\n                                                    <span id=\"subtotal\">{{ subtotal }}</span>\r\n                                                </span>\r\n                                            </li>\r\n\r\n                                            {% for key, value in tax_dict.items %}\r\n                                                {% for i, j in value.items %}\r\n                                                    <li style=\"list-style-type: none;\">\r\n                                                        {{ key }} <small>({{ i }}%)</small>\r\n                                                        <span class=\"price float-right\">\r\n                                                            <span class=\"currency\">$</span>\r\n                                                            <span id=\"tax-{{ key }}\">{{ j }}</span>\r\n                                                        </span>\r\n                                                    </li>\r\n                                                {% endfor %}\r\n                                            {% endfor %}\r\n\r\n\r\n                                            <li style=\"list-style-type: none; font-weight: 600;\">\r\n                                                TOTAL\r\n                                                <span class=\"price float-right\">\r\n                                                    <span class=\"currency\">$</span>\r\n                                                    <span id=\"total\">{{ grand_total }}</span>\r\n                                                </span>\r\n                                            </li>\r\n                                            {% if order.payment_method == 'PayPal' %}\r\n                                                <!--PayPal Checkout Button-->\r\n                                                <div id=\"paypal-button-container\"></div>\r\n                                            {% elif order.payment_method == 'RazorPay' %}\r\n                                                <div id=\"rzp_payment_button\">\r\n                                                    <button class=\"btn btn-danger w-100 p-2\" id=\"rzp-button1\">Pay with RazorPay</button>\r\n                                                    <script src=\"https://checkout.razorpay.com/v1/checkout.js\"></script>\r\n                                                </div>\r\n                                            {% endif %}\r\n                                        </ul>\r\n                                    </div>                                    \r\n                                </div>\r\n                            </div>                            \r\n                        </div>\r\n                    </div>\r\n                </div>                 \r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<!-- Main Section End -->\r\n\r\n<script>\r\n\r\n \n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
