        "description": "Código-fonte: `autoTestRemote.js`",
        "file": "autoTestRemote.js",
        "code": "/**\r\n * AutoTest remoto — fila de jobs + registro de agentes nas estações de campo.\r\n * Segurança estilo Veyon: chave por agente + jobs assinados pelo servidor.\r\n */\r\nconst fs = require('fs');\r\nconst path = require('path');\r\nconst crypto = require('crypto');\r\nconst os = require('os');\r\nconst remoteSec = require('./autoTestRemoteSecurity');\r\nconst autoTest = require('./autoTest');\r\n\r\nconst DATA_DIR = path.join(__dirname, 'data');\r\nconst STORE_FILE = path.join(DATA_DIR, 'autotest-remote.json');\r\n\r\nconst ONLINE_MS = 90 * 1000;\r\nconst JOB_PENDING_TIMEOUT_MS = Number(process.env.AUTOTEST_REMOTE_PENDING_MS) || 10 * 60 * 1000;\r\nconst JOB_CLAIMED_TIMEOUT_MS = Number(process.env.AUTOTEST_REMOTE_CLAIMED_MS) || 15 * 60 * 1000;\r\nconst MAX_RESULT_BYTES = 2 * 1024 * 1024;\r\nconst MAX_JOBS = 200;\r\nconst LEGACY_TOKEN_ENABLED = process.env.AUTOTEST_REMOTE_LEGACY !== '0';\r\n\r\nfunction ensureStore() {\r\n  if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });\r\n}\r\n\r\nfunction defaultStore() {\r\n  return {\r\n    version: 2,\r\n    securityMode: 'veyon',\r\n    agentToken: crypto.randomBytes(24).toString('hex'),\r\n    agents: {},\r\n    jobs: []\r\n  };\r\n}\r\n\r\nfunction loadStore() {\r\n  ensureStore();\r\n  if (!fs.existsSync(STORE_FILE)) {\r\n    const s = defaultStore();\r\n    saveStore(s);\r\n    return s;\r\n  }\r\n  try {\r\n    const raw = JSON.parse(fs.readFileSync(STORE_FILE, 'utf8'));\r\n    return {\r\n      ...defaultStore(),\r\n      ...raw,\r\n      agentToken: raw.agentToken || crypto.randomBytes(24).toString('hex'),\r\n      agents: raw.agents && typeof raw.agents === 'object' ? raw.agents : {},\r\n      jobs: Array.isArray(raw.jobs) ? raw.jobs : []\r\n    };\r\n  } catch {\r\n    const s = defaultStore();\r\n    saveStore(s);\r\n    return s;\r\n  }\r\n}\r\n\r\nfunction saveStore(store) {\r\n  ensureStore();\r\n  const tmp = `${STORE_FILE}.tmp`;\r\n  fs.writeFileSync(tmp, JSON.stringify(store, null, 2), 'utf8');\r\n  fs.renameSync(tmp, STORE_FILE);\r\n}\r\n\r\nfunction getAgent(agentId) {\r\n  const store = loadStore();\r\n  return store.agents[normalizeAgentId(agentId)] || null;\r\n}\r\n\r\nfunction verifyAgentToken(token) {\r\n  if (!LEGACY_TOKEN_ENABLED) return false;\r\n  const store = loadStore();\r\n  return token && token === store.agentToken;\r\n}\r\n\r\nfunction normalizeAgentId(hostname) {\r\n  return String(hostname || '').trim().toLowerCase().replace(/[^a-z0-9._-]+/g, '-').slice(0, 64);\r\n}\r\n\r\nfunction sanitizeAgent(agent, online) {\r\n  return {\r\n    agentId: agent.agentId,\r\n    hostname: agent.hostname,\r\n    ip: agent.ip,\r\n    user: agent.user,\r\n    agentVersion: agent.agentVersion,\r\n    securityMode: agent.publicKey ? 'veyon' : 'legacy',\r\n    firstSeen: agent.firstSeen,\r\n    lastSeen: agent.lastSeen,\r\n    lastJobAt: agent.lastJobAt,\r\n    online\r\n  };\r\n}\r\n\r\nfunction touchAgent(payload = {}, opts = {}) {\r\n  const store = loadStore();\r\n  const hostname = String(payload.hostname || os.hostname()).trim();\r\n  const agentId = normalizeAgentId(payload.agentId || hostname);\r\n  if (!agentId) return { ok: false, error: 'Hostname inválido.' };\r\n\r\n  const prev = store.agents[agentId] || {};\r\n  if (opts.requireRegistered && !prev.publicKey && !prev.legacy && !opts.legacy) {\r\n    return { ok: false, error: 'Agente não pareado. Gere código na sala TI e execute -Enroll na estação.' };\r\n  }\r\n\r\n  const agent = {\r\n    ...prev,\r\n    agentId,\r\n    hostname,\r\n    ip: payload.ip || prev.ip || null,\r\n    user: payload.user || prev.user || null,\r\n    agentVersion: payload.agentVersion || prev.agentVersion || '1.0',\r\n    firstSeen: prev.firstSeen || new Date().toISOString(),\r\n    lastSeen: new Date().toISOString(),\r\n    lastJobAt: prev.lastJobAt || null,\r\n    legacy: opts.legacy ? true : (prev.legacy || false)\r\n  };\r\n  store.agents[agentId] = agent;\r\n  saveStore(store);\r\n  return { ok: true, agent };\r\n}\r\n\r\nfunction enrollAgent(payload = {}) {\r\n  const code = String(payload.pairingCode || '').trim().toUpperCase();\r\n  const publicKey = String(payload.publicKey || '').trim();\r\n  if (!code) return { ok: false, error: 'Informe o código de pareamento.' };\r\n  if (!publicKey.includes('BEGIN PUBLIC KEY')) {\r\n    return { ok: false, error: 'Chave pública inválida.' };\r\n  }\r\n  if (!remoteSec.consumePairingCode(code)) {\r\n    return { ok: false, error: 'Código de pareamento inválido ou expirado.' };\r\n  }\r\n\r\n  const hostname = String(payload.hostname || os.hostname()).trim();\r\n  const agentId = normalizeAgentId(payload.agentId || hostname);\r\n  if (!agentId) return { ok: false, error: 'Hostname inválido.' };\r\n\r\n  const store = loadStore();\r\n  const prev = store.agents[agentId] || {};\r\n  store.agents[agentId] = {\r\n    ...prev,\r\n    agentId,\r\n    hostname,\r\n    ip: payload.ip || prev.ip || null,\r\n    publicKey,\r\n    legacy: false,\r\n    enrolledAt: new Date().toISOString(),\r\n    firstSeen: prev.firstSeen || new Date().toISOString(),\r\n    lastSeen: new Date().toISOString(),\r\n    agentVersion: payload.agentVersion || '2.0'\r\n  };\r\n  saveStore(store);\r\n\r\n  remoteSec.ensureServerKeys();\r\n  return {\r\n    ok: true,\r\n    agentId,\r\n    hostname,\r\n    serverPublicKey: remoteSec.getServerPublicKey(),\r\n    securityMode: 'veyon'\r\n  };\r\n}\r\n\r\nfunction expireStaleJobs(store) {\r\n  const now = Date.now();\r\n  let changed = false;\r\n  for (const job of store.jobs) {\r\n    if (!job || (job.status !== 'pending' && job.status !== 'claimed')) continue;\r\n    const base = job.status === 'claimed' && job.claimedAt ? job.claimedAt : job.createdAt;\r\n    const limit = job.status === 'claimed' ? JOB_CLAIMED_TIMEOUT_MS : JOB_PENDING_TIMEOUT_MS;\r\n    const age = now - new Date(base).getTime();\r\n    if (age > limit) {\r\n      const wasClaimed = job.status === 'claimed';\r\n      job.status = 'timeout';\r\n      job.error = wasClaimed\r\n        ? 'Tempo esgotado durante execução remota.'\r\n        : 'Tempo esgotado aguardando agente remoto.';\r\n      job.completedAt = new Date().toISOString();\r\n      changed = true;\r\n    }\r\n  }\r\n  return changed;\r\n}\r\n\r\nfunction listAgents() {\r\n  const store = loadStore();\r\n  expireStaleJobs(store);\r\n  saveStore(store);\r\n  const now = Date.now();\r\n  const agents = Object.values(store.agents)\r\n    .map((a) => sanitizeAgent(a, (now - new Date(a.lastSeen).getTime()) <= ONLINE_MS))\r\n    .sort((a, b) => {\r\n      if (a.online !== b.online) return a.online ? -1 : 1;\r\n      return (b.lastSeen || '').localeCompare(a.lastSeen || '');\r\n    });\r\n  return {\r\n    ok: true,\r\n    agents,\r\n    securityMode: 'veyon',\r\n    legacyTokenEnabled: LEGACY_TOKEN_ENABLED\r\n  };\r\n}\r\n\r\nfunction resolveAgentTarget(target) {\r\n  const store = loadStore();\r\n  const raw = String(target || '').trim();\r\n  if (!raw) return { ok: false, error: 'Informe IP ou hostname da estação.' };\r\n\r\n  const agents = Object.values(store.agents);\r\n  const ipMatch = agents.find((a) => a.ip && a.ip === raw);\r\n  if (ipMatch) return { ok: true, agent: ipMatch, matchedBy: 'ip' };\r\n\r\n  const norm = normalizeAgentId(raw);\r\n  if (store.agents[norm]) return { ok: true, agent: store.agents[norm], matchedBy: 'agentId' };\r\n\r\n  const hostLower = raw.toLowerCase(\n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
        "implementation": [
          "path: autoTestRemote.js",
          "GitHub: https://github.com/CanonEngineer/Professional-Scanner/blob/main/autoTestRemote.js"
        ]
