        "file": "canonReportPdf.js",
        "code": "/**\r\n * Utilitários PDF compartilhados — relatórios NetScan Canon\r\n */\r\nconst {\r\n  C, REPORT_VERSION, REPORT_SITE, REPORT_YEAR, fmtDatePt, statusInfo\r\n} = require('./canonReportTheme');\r\n\r\nconst PAGE = { left: 42, right: 553, width: 511, footerY: 762, contentBottom: 735 };\r\n\r\nfunction createPdfContext(doc) {\r\n  let pageNum = 0;\r\n  const ctx = {\r\n    doc,\r\n    pageNum,\r\n    PAGE,\r\n    y: 0,\r\n\r\n    ensureSpace(needed) {\r\n      if (doc.y + needed > PAGE.contentBottom) ctx.newPage(false);\r\n    },\r\n\r\n    newPage(isFirst = false) {\r\n      if (!isFirst) doc.addPage();\r\n      pageNum += 1;\r\n      ctx.pageNum = pageNum;\r\n      doc.save();\r\n      doc.rect(0, 0, 595, 44).fill(C.brand);\r\n      doc.fillColor(C.white).font('Helvetica-Bold').fontSize(11).text('NetScan Canon', PAGE.left, 14);\r\n      doc.fillColor(C.accent).font('Helvetica').fontSize(8).text(ctx._topSubtitle || 'Relatório Profissional', PAGE.left, 28);\r\n      doc.fillColor('#bae6fd').fontSize(7).text(`v${REPORT_VERSION}`, PAGE.left, PAGE.width, 14, { align: 'right', width: PAGE.width });\r\n      doc.restore();\r\n      doc.y = 52;\r\n    },\r\n\r\n    drawMetaBox(title, rows) {\r\n      const h = 28 + rows.length * 14 + 8;\r\n      ctx.ensureSpace(h);\r\n      const x = PAGE.left;\r\n      const y = doc.y;\r\n      const w = PAGE.width;\r\n      doc.rect(x, y, w, 22).fill(C.brandDark);\r\n      doc.fillColor(C.white).font('Helvetica-Bold').fontSize(11).text(title, x + 8, y + 6);\r\n      doc.rect(x, y + 22, w, rows.length * 14 + 8).strokeColor(C.border).lineWidth(1).stroke();\r\n      let ry = y + 28;\r\n      rows.forEach(([label, value]) => {\r\n        doc.fillColor(C.muted).font('Helvetica-Bold').fontSize(8).text(`${label}`, x + 10, ry, { continued: true, width: 110 });\r\n        doc.fillColor(C.body).font('Helvetica').fontSize(8).text(String(value ?? '—'), { width: w - 130 });\r\n        ry += 14;\r\n      });\r\n      doc.y = y + h + 10;\r\n    },\r\n\r\n    drawVerdictBanner(verdict, grade, pct, tested, ok) {\r\n      const h = 88;\r\n      ctx.ensureSpace(h + 10);\r\n      const x = PAGE.left;\r\n      const y = doc.y;\r\n      const w = PAGE.width;\r\n      const bg = ok ? C.pass : (verdict.includes('RESSALV') ? C.warn : C.fail);\r\n      doc.roundedRect(x, y, w, h, 6).fill(bg);\r\n      doc.fillColor(C.white).font('Helvetica-Bold').fontSize(11)\r\n        .text(ok ? '✔ RESULTADO FINAL' : '❌ RESULTADO FINAL', x, y + 10, { width: w, align: 'center' });\r\n      doc.fontSize(20).text(String(verdict).toUpperCase(), { align: 'center' });\r\n      doc.fontSize(10).font('Helvetica')\r\n        .text(`Nota: ${grade}   ·   Taxa de sucesso: ${pct != null ? pct + '%' : '—'}   ·   ${tested || 0} testes executados`, { align: 'center' });\r\n      doc.y = y + h + 14;\r\n    },\r\n\r\n    drawStatCards(cards) {\r\n      const cardW = (PAGE.width - (cards.length - 1) * 8) / cards.length;\r\n      const h = 46;\r\n      ctx.ensureSpace(h + 8);\r\n      const y = doc.y;\r\n      cards.forEach((card, i) => {\r\n        const x = PAGE.left + i * (cardW + 8);\r\n        doc.roundedRect(x, y, cardW, h, 4).fill(C.bg).strokeColor(C.border).stroke();\r\n        doc.fillColor(C.muted).font('Helvetica').fontSize(7).text(card.label, x + 6, y + 8, { width: cardW - 12, align: 'center' });\r\n        doc.fillColor(card.color || C.title).font('Helvetica-Bold').fontSize(card.small ? 10 : 14)\r\n          .text(String(card.value), x + 6, y + 22, { width: cardW - 12, align: 'center' });\r\n      });\r\n      doc.y = y + h + 12;\r\n    },\r\n\r\n    drawProgressBar(label, pct, color) {\r\n      ctx.ensureSpace(22);\r\n      doc.fillColor(C.body).font('Helvetica-Bold').fontSize(8).text(label, PAGE.left, doc.y);\r\n      const barY = doc.y + 12;\r\n      const barW = PAGE.width;\r\n      doc.rect(PAGE.left, barY, barW, 10).fill('#e2e8f0');\r\n      const fillW = Math.max(0, Math.min(barW, (barW * (pct || 0)) / 100));\r\n      if (fillW > 0) doc.rect(PAGE.left, barY, fillW, 10).fill(color || C.pass);\r\n      doc.fillColor(C.body).font('Helvetica').fontSize(7)\r\n        .text(`${pct != null ? pct + '%' : ''}`, PAGE.left + barW - 30, barY + 1);\r\n      doc.y = barY + 16;\r\n    },\r\n\r\n    drawCountBars(pass, warn, fail, total) {\r\n      const max = Math.max(pass, warn, fail, 1);\r\n      const items = [\r\n        { label: 'OK', count: pass, color: C.pass },\r\n        { label: 'Avisos', count: warn, color: C.warn },\r\n        { label: 'Falhas', count: fail, color: C.fail }\r\n      ];\r\n      items.forEach((item) => {\r\n        ctx.ensureSpace(16);\r\n        doc.fillColor(C.body).font('Helvetica-Bold').fontSize(8).text(item.label.padEnd(8), PAGE.left, doc.y, { continued: true, width: 50 });\r\n        const barX = PAGE.left + 52;\r\n        const barMaxW = PAGE.width - 80;\r\n        const barW = Math.round((item.count / max) * barMaxW);\r\n        doc.rect(barX, doc.y + 2, barMaxW, 8).fill('#e2e8f0');\r\n        if (barW > 0) doc.rect(barX, doc.y + 2, barW, 8).fill(item.color);\r\n        doc.fillColor(C.body).font('Helvetica').fontSize(8).text(String(item.count), barX + barMaxW + 6, doc.y);\r\n        doc.y += 14;\r\n      });\r\n    },\r\n\r\n    drawSectionTitle(text) {\r\n      ctx.ensureSpace(24);\r\n      doc.font('Helvetica-Bold').fontSize(11).fillColor(C.brand).text(text);\r\n      const y = doc.y;\r\n      doc.moveTo(PAGE.left, y).lineTo(PAGE.right, y).strokeColor(C.accent).lineWidth(1.5).stroke();\r\n      doc.lineWidth(1);\r\n      doc.moveDown(0.5);\r\n    },\r\n\r\n    drawKeyValueTable(rows) {\r\n      ctx.ensureSpace(rows.length * 16 + 8);\r\n      const colKey = 130;\r\n      let y = doc.y;\r\n      rows.forEach(([k, v], i) => {\r\n        if (i % 2 === 0) doc.rect(PAGE.left, y - 1, PAGE.width, 15).fill(C.bg);\r\n        doc.fillColor(C.muted).font('Helvetica-Bold').fontSize(8).text(k, PAGE.left + 6, y, { width: colKey });\r\n        doc.fillColor(C.body).font('Helvetica').fontSize(8).text(String(v ?? '—'), PAGE.left + colKey, y, { width: PAGE.width - colKey - 6 });\r\n        y += 15;\r\n      });\r\n      doc.y = y + 6;\r\n    },\r\n\r\n    drawAlertBox(title, lines, type = 'warn') {\r\n      const color = type === 'fail' ? C.fail : C.warn;\r\n      const h = 20 + lines.length * 12 + 10;\r\n      ctx.ensureSpace(h);\r\n      const y = doc.y;\r\n      doc.rect(PAGE.left, y, PAGE.width, h).fill('#fffbeb').strokeColor(color).lineWidth(1).stroke();\r\n      doc.fillColor(color).font('Helvetica-Bold').fontSize(9).text(title, PAGE.left + 8, y + 6);\r\n      let ly = y + 20;\r\n      lines.forEach((line) => {\r\n        doc.fillColor(C.body).font('Helvetica').fontSize(8).text(line, PAGE.left + 10, ly, { width: PAGE.width - 20 });\r\n        ly += 12;\r\n      });\r\n      doc.y = y + h + 8;\r\n    },\r\n\r\n    drawFinalBox(lines) {\r\n      const h = 24 + lines.length * 13 + 16;\r\n      ctx.ensureSpace(h);\r\n      const x = PAGE.left;\r\n      const y = doc.y;\r\n      const w = PAGE.width;\r\n      doc.rect(x, y, w, h).strokeColor(C.brand).lineWidth(1.5).stroke();\r\n      doc.rect(x, y, w, 20).fill(C.brand);\r\n      doc.fillColor(C.white).font('Helvetica-Bold').fontSize(10)\r\n        .text('RESULTADO DO AUTOTESTE', x, y + 5, { width: w, align: 'center' });\r\n      let ly = y + \n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
