        "layer": "file",
        "title": "platform.js",
        "description": "Código-fonte: `public/platform.js`",
        "file": "public/platform.js",
        "code": "/* NetScan Canon Platform UI — módulo aditivo */\r\n(function () {\r\n  async function readApiJson(res) {\r\n    if (typeof window.readApiJson === 'function') return window.readApiJson(res);\r\n    const ct = (res.headers.get('content-type') || '').toLowerCase();\r\n    if (ct.includes('application/json')) return res.json().catch(() => ({}));\r\n    throw new Error(`HTTP ${res.status}`);\r\n  }\r\n\r\n  function esc(s) {\r\n    if (typeof escapeHtml === 'function') return escapeHtml(s);\r\n    return String(s ?? '').replace(/[&<>\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\r\n  }\r\n\r\n  async function apiGet(path) {\r\n    const res = await fetch(path);\r\n    if (res.status === 401) {\r\n      if (typeof window.gateCanonModalsArea === 'function') {\r\n        window.gateCanonModalsArea({ target: 'platform' });\r\n      }\r\n      throw new Error('Autenticação necessária — faça login.');\r\n    }\r\n    const data = await readApiJson(res);\r\n    if (!res.ok || data.ok === false) throw new Error(data.error || `HTTP ${res.status}`);\r\n    return data;\r\n  }\r\n\r\n  async function apiPost(path, body) {\r\n    const res = await fetch(path, {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify(body || {})\r\n    });\r\n    if (res.status === 401) {\r\n      if (typeof window.gateCanonModalsArea === 'function') {\r\n        window.gateCanonModalsArea({ target: 'platform' });\r\n      }\r\n      throw new Error('Autenticação necessária — faça login.');\r\n    }\r\n    const data = await readApiJson(res);\r\n    if (!res.ok || data.ok === false) throw new Error(data.error || `HTTP ${res.status}`);\r\n    return data;\r\n  }\r\n\r\n  const STATUS_PULSE_MS = 60 * 1000;\r\n  let statusPulseTimer = null;\r\n  let statusPulseVisible = true;\r\n\r\n  function stopStatusPulse() {\r\n    if (statusPulseTimer) {\r\n      clearTimeout(statusPulseTimer);\r\n      statusPulseTimer = null;\r\n    }\r\n  }\r\n\r\n  function applyStatusPulseVisibility(el, visible) {\r\n    if (!el) return;\r\n    statusPulseVisible = visible;\r\n    el.classList.toggle('platform-status-hidden', !visible);\r\n    el.classList.toggle('platform-status-visible', visible);\r\n  }\r\n\r\n  function scheduleStatusPulseToggle(el) {\r\n    stopStatusPulse();\r\n    if (!el) return;\r\n    const backdrop = document.getElementById('platform-modal-backdrop');\r\n    if (!backdrop || backdrop.classList.contains('hidden')) return;\r\n    statusPulseTimer = setTimeout(() => {\r\n      applyStatusPulseVisibility(el, !statusPulseVisible);\r\n      scheduleStatusPulseToggle(el);\r\n    }, STATUS_PULSE_MS);\r\n  }\r\n\r\n  function startStatusPulse(el) {\r\n    if (!el) return;\r\n    applyStatusPulseVisibility(el, true);\r\n    scheduleStatusPulseToggle(el);\r\n  }\r\n\r\n  function setStatus(id, text, kind = '') {\r\n    const el = document.getElementById(id);\r\n    if (!el) return;\r\n    el.textContent = text || '';\r\n    const footer = id === 'platform-status' ? ' platform-status-footer' : '';\r\n    el.className = `ad-status-bar${footer}${kind ? ` ${kind}` : ''}`;\r\n    if (id === 'platform-status') startStatusPulse(el);\r\n  }\r\n\r\n  function renderJson(el, obj) {\r\n    if (!el) return;\r\n    el.textContent = JSON.stringify(obj, null, 2);\r\n  }\r\n\r\n  function switchPlatformTab(tab) {\r\n    document.querySelectorAll('#platform-modal-backdrop .platform-tab').forEach((el) => {\r\n      const active = el.dataset.platformTab === tab;\r\n      el.classList.toggle('active', active);\r\n      el.setAttribute('aria-selected', active ? 'true' : 'false');\r\n    });\r\n    document.querySelectorAll('#platform-modal-backdrop .platform-tab-panel').forEach((panel) => {\r\n      panel.classList.toggle('hidden', panel.id !== `platform-tab-${tab}`);\r\n    });\r\n    const loaders = {\r\n      summary: loadPlatformSummary,\r\n      drift: loadPlatformDrift,\r\n      correlation: loadPlatformCorrelation,\r\n      tls: loadPlatformTls,\r\n      nac: loadPlatformNac,\r\n      lifecycle: loadPlatformLifecycle,\r\n      passive: loadPlatformPassive,\r\n      agent: loadPlatformAgent,\r\n      config: loadPlatformConfig\r\n    };\r\n    if (loaders[tab]) loaders[tab]().catch((err) => setStatus('platform-status', err.message, 'error'));\r\n  }\r\n\r\n  async function loadPlatformSummary() {\r\n    setStatus('platform-status', 'Carregando resumo…');\r\n    const data = await apiGet('/api/platform/summary');\r\n    const box = document.getElementById('platform-summary-body');\r\n    if (!box) return;\r\n    box.innerHTML = `\r\n      <div class=\"platform-summary-grid\">\r\n        <div class=\"platform-stat-card\"><strong>${data.scan?.total ?? 0}</strong><span>Hosts no scan</span></div>\r\n        <div class=\"platform-stat-card\"><strong>${data.scan?.active ?? 0}</strong><span>Ativos</span></div>\r\n        <div class=\"platform-stat-card\"><strong>${data.drift?.added ?? '—'}</strong><span>Drift (+)</span></div>\r\n        <div class=\"platform-stat-card\"><strong>${data.drift?.removed ?? '—'}</strong><span>Drift (−)</span></div>\r\n        <div class=\"platform-stat-card\"><strong>${data.lifecycle?.total ?? '—'}</strong><span>CMDB assets</span></div>\r\n        <div class=\"platform-stat-card\"><strong>${data.passive?.count ?? '—'}</strong><span>ARP passivo</span></div>\r\n      </div>\r\n      <p class=\"ad-section-hint\">Site ativo: <strong>${esc(data.site?.name || 'Principal')}</strong></p>\r\n    `;\r\n    setStatus('platform-status', 'Resumo atualizado.', 'ok');\r\n  }\r\n\r\n  async function loadPlatformDrift() {\r\n    setStatus('platform-status', 'Calculando drift…');\r\n    const data = await apiGet('/api/platform/drift');\r\n    renderJson(document.getElementById('platform-drift-body'), data);\r\n    setStatus('platform-status', data.message || 'Drift carregado.', data.drift ? 'ok' : '');\r\n  }\r\n\r\n  async function loadPlatformCorrelation() {\r\n    setStatus('platform-status', 'Correlacionando IP + AD + switch…');\r\n    const data = await apiGet('/api/platform/correlation?limit=20');\r\n    renderJson(document.getElementById('platform-correlation-body'), data);\r\n    setStatus('platform-status', `${data.count || 0} host(s) correlacionado(s).`, 'ok');\r\n  }\r\n\r\n  async function loadPlatformTls() {\r\n    setStatus('platform-status', 'Escaneando certificados TLS (443)…');\r\n    const data = await apiPost('/api/platform/tls-scan', { maxHosts: 24, ports: [443] });\r\n    renderJson(document.getElementById('platform-tls-body'), data);\r\n    setStatus('platform-status', `${data.scanned || 0} teste(s) · ${data.expiringCount || 0} expirando ≤30d`, 'ok');\r\n  }\r\n\r\n  async function loadPlatformNac() {\r\n    setStatus('platform-status', 'Avaliando prontidão NAC…');\r\n    const data = await apiGet('/api/platform/nac?limit=30');\r\n    renderJson(document.getElementById('platform-nac-body'), data);\r\n    setStatus('platform-status', `${data.count || 0} avaliação(ões) NAC.`, 'ok');\r\n  }\r\n\r\n  async function loadPlatformLifecycle() {\r\n    setStatus('platform-status', 'Carregando CMDB lifecycle…');\r\n    const data = await apiGet('/api/platform/lifecycle');\r\n    const box = document.getElementById('platform-lifecycle-body');\r\n    if \n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
