        "file": "perfil/templates/perfil/login.html",
        "code": "{% extends 'base.html' %}\r\n\r\n{% load static %}\r\n\r\n{% block titulo %}Login | {% endblock %}\r\n\r\n{% block conteudo %}\r\n\r\n<head>\r\n    <title>Login</title>\r\n    {% include 'parciais/_headlogin.html' %}\r\n\r\n</head>\r\n\r\n<body>\r\n    <section class=\"ftco-section\">\r\n        {% if not request.user.is_authenticated %}\r\n        <div class=\"container\">\r\n            <div class=\"row justify-content-center\">\r\n                <div class=\"col-md-6 text-center mb-1\">\r\n                    <h2 class=\"heading-section\">Login</h2>\r\n                </div>\r\n            </div>\r\n            <div class=\"row justify-content-center\">\r\n                <div class=\"col-md-6 col-lg-4\">\r\n                    <div class=\"login-wrap py-5\">\r\n                        <div class=\"img d-flex align-items-center justify-content-center\"\r\n                            style=\"background-image: url(/media/bg.jpg);\"></div>\r\n                        <h3 class=\"text-center mb-0\">Seja bem vindo.</h3>\r\n                        <p class=\"text-center\">Entre com suas informações abaixo.</p>\r\n                        <form method=\"POST\" action=\"{% url 'perfil:login' %}\">\r\n                            {% csrf_token %}\r\n                            <div class=\"form-group\">\r\n                                <div class=\"icon d-flex align-items-center justify-content-center\"><span\r\n                                        class=\"fa fa-user\"></span></div>\r\n                                <input type=\"text\" name='username' class=\"form-control\" id=\"InputUsuario1\"\r\n                                    aria-describedby=\"usuarioHelp\" placeholder=\"Digite seu usuário\">\r\n                            </div>\r\n\r\n                            <div class=\"form-group\">\r\n                                <div class=\"icon d-flex align-items-center justify-content-center\"><span\r\n                                        class=\"fa fa-lock\"></span></div>\r\n                                <input name='password' type=\"password\" class=\"form-control\" id=\"exampleInputPassword1\"\r\n                                    placeholder=\"Digite sua senha\">\r\n                            </div>\r\n                            <div class=\"form-group d-md-flex\">\r\n                                <div class=\"w-100 text-md-right\">\r\n                                    <!--Esqueceu a senha-->\r\n                                    <a href=\"#\"></a>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"form-group\">\r\n                                <button type=\"submit\"\r\n                                    class=\"btn form-control btn-primary rounded submit px-3\">Entrar</button>\r\n                            </div>\r\n                        </form>\r\n                        <div class=\"w-100 text-center mt-4 text\">\r\n                            <p class=\"mb-0\">Você não tem uma conta?</p>\r\n                            <a href=\"{% url 'perfil:criar' %}\">Cadastrar</a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        {% endif %}\r\n    </section>\r\n</body>\r\n\r\n{% include 'parciais/_bodylogin.html' %}\r\n\r\n{% endblock %}",
