      {
        "id": "php-dao-file-class-sql-php",
        "parent": "php-dao-dir-class",
        "layer": "file",
        "title": "Sql.php",
        "description": "Código-fonte: `class/Sql.php`",
        "file": "class/Sql.php",
        "code": "<?php\r\n\r\nclass Sql extends PDO {\r\n\r\n\tprivate $conn;\r\n\r\n\tpublic function __construct(){\r\n\r\n\t\t$servername = \"127.0.0.1:3306\";\r\n\t\t$username = \"root\";\r\n\t\t$password = \"zilda19121956\";\t\t\r\n\r\n\t\ttry {\r\n\t\t    $this->conn = new PDO(\"mysql:host=$servername;dbname=dbphp7\", $username, $password);\r\n\t\t    // set the PDO error mode to exception\r\n\t\t    $this->conn->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);\r\n\t\t    echo \"Connected successfully\";\r\n\t\t    echo \"<br/>\";\r\n\t\t    echo \"<br/>\";\r\n\t\t}\r\n\t\tcatch(PDOException $e){\r\n\t\t    echo \"Connection failed: \" . $e->getMessage();\r\n\t\t    }\r\n\r\n\t\t}\r\n\r\n\tprivate function setParams($statement, $parameters = array()){\r\n\r\n\t\tforeach ($parameters as $key => $value) {\r\n\t\t\t\r\n\t\t\t$this->setParam($statement, $key, $value);\r\n\r\n\t\t}\r\n\r\n\t}\r\n\r\n\tprivate function setParam($statement, $key, $value){\r\n\r\n\t\t$statement->bindParam($key, $value);\r\n\r\n\t}\r\n\r\n\tpublic function query($rawQuery, $params = array()){\r\n\r\n\t\t$stmt = $this->conn->prepare($rawQuery);\r\n\r\n\t\t$this->setParams($stmt, $params);\t\r\n\r\n\t\t$stmt->execute();\r\n\r\n\t\treturn $stmt;\t\r\n\r\n\t}\r\n\r\n\tpublic function select($rawQuery, $params = array()):array{\r\n\r\n\r\n\t\t$stmt = $this->query($rawQuery, $params);\r\n\r\n\t\treturn $stmt->fetchAll(PDO::FETCH_ASSOC);\r\n\r\n\r\n\t}\r\n\r\n}\r\n\r\n?>",
        "implementation": [
          "path: class/Sql.php",
          "GitHub: https://github.com/CanonEngineer/PHPDaoProject/blob/main/class/Sql.php"
        ]
      },
      {
        "id": "php-dao-file-class-usuario-php",
        "parent": "php-dao-dir-class",
        "layer": "file",
        "title": "Usuario.php",
        "description": "Código-fonte: `class/Usuario.php`",
        "file": "class/Usuario.php",
        "code": "<?php\r\n\r\nclass Usuario {\r\n\r\n\tprivate $idusuario;\r\n\tprivate $deslogin;\r\n\tprivate $dessenha;\r\n\tprivate $dtcadastro;\r\n\r\n\tpublic function getIdusuario(){\r\n\t\treturn $this->idusuario;\r\n\t}\r\n\r\n\tpublic function setIdusuario($value){\r\n\t\t$this->idusuario = $value;\r\n\t}\r\n\r\n\tpublic function getDeslogin(){\r\n\t\treturn $this->deslogin;\r\n\t}\r\n\r\n\tpublic function setDeslogin($value){\r\n\t\t$this->deslogin = $value;\r\n\t}\r\n\r\n\tpublic function getDessenha(){\r\n\t\treturn $this->dessenha;\r\n\t}\r\n\r\n\tpublic function setDessenha($value){\r\n\t\t$this->dessenha = $value;\r\n\t}\r\n\r\n\tpublic function getDtcadastro(){\r\n\t\treturn $this->dtcadastro;\r\n\t}\r\n\r\n\tpublic function setDtcadastro($value){\r\n\t\t$this->dtcadastro = $value;\r\n\t}\r\n\r\n\tpublic function loadById($id){\r\n\r\n\t\t$sql = new Sql();\r\n\r\n\t\t$results = $sql->select(\"SELECT * FROM tb_usuarios WHERE idusuario = :ID\", array(\r\n\t\t\t\":ID\"=>$id\r\n\t\t));\r\n\r\n\t\tif (count($results) > 0) {\r\n\r\n\t\t\t$this->setData($results[0]);\r\n\r\n\t\t}\r\n\r\n\t}\r\n\r\n\tpublic static function getList(){\r\n\r\n\t\t$sql = new Sql();\r\n\r\n\t\treturn $sql->select(\"SELECT * FROM tb_usuarios ORDER BY deslogin;\");\r\n\r\n\t}\r\n\r\n\tpublic static function search($login){\r\n\r\n\t\t$sql = new Sql();\r\n\r\n\t\treturn $sql->select(\"SELECT * FROM tb_usuarios WHERE deslogin LIKE :SEARCH ORDER BY deslogin\", array(\r\n\r\n\t\t\t':SEARCH'=>\"%\".$login.\"%\"\r\n\r\n\t\t));\r\n\r\n\t}\r\n\r\n\tpublic function login($login, $password){\r\n\r\n\t\t$sql = new Sql();\r\n\r\n\t\t$results = $sql->select(\"SELECT * FROM tb_usuarios WHERE deslogin = :LOGIN AND dessenha = :PASSWORD\", array(\r\n\t\t\t\":LOGIN\"=>$login,\r\n\t\t\t\":PASSWORD\"=>$password\r\n\t\t));\r\n\r\n\t\tif (count($results) > 0) {\t\t\t\r\n\r\n\t\t\t$this->setData($results[0]);\r\n\r\n\t\t} else {\r\n\r\n\t\t\tthrow new Exception(\"Login e/ou senha inválidos.\");\r\n\r\n\t\t}\r\n\r\n\t}\r\n\r\n\tpublic function setData($data){\r\n\r\n\t\t$this->setIdusuario($data['idusuario']);\r\n\t\t$this->setDeslogin($data['deslogin']);\r\n\t\t$this->setDessenha($data['dessenha']);\r\n\t\t$this->setDtcadastro(new DateTime($data['dtcadastro']));\r\n\r\n\t}\r\n\r\n\tpublic function insert(){\r\n\r\n\t\t$sql = new Sql();\r\n\r\n\t\t$results = $sql->select(\"CALL sp_usuarios_insert(:LOGIN, :PASSWORD)\", array(\r\n\t\t\t':LOGIN'=>$this->getDeslogin(),\r\n\t\t\t':PASSWORD'=>$this->getDessenha()\r\n\t\t));\r\n\r\n\t\tif (count($results) > 0){\r\n\t\t\t$this->setData($results[0]);\r\n\t\t}\r\n\r\n\t}\r\n\r\n\tpublic function __construct($login = \"\", $password = \"\"){\r\n\r\n\t\t$this->setDeslogin($login);\r\n\t\t$this->setDessenha($password);\r\n\r\n\t}\r\n\r\n\tpublic function update($login, $password){\r\n\r\n\t\t$this->setDeslogin($login);\r\n\t\t$this->setDessenha($password);\r\n\r\n\t\t$sql = new Sql();\r\n\r\n\t\t$sql->query(\"UPDATE tb_usuarios SET deslogin = :LOGIN, dessenha = :PASSWORD WHERE idusuario = :ID\", array(\r\n\t\t\t':LOGIN'=>$this->getDeslogin(),\r\n\t\t\t':PASSWORD'=>$this->getDessenha(),\r\n\t\t\t':ID'=>$this->getIdusuario()\t\t\t\r\n\t\t));\r\n\r\n\t}\r\n\r\n\tpublic function delete(){\r\n\t\t\r\n\t\t$sql = new Sql();\r\n\r\n\t\t$sql->query(\"DELETE FROM tb_usuarios WHERE idusuario = :ID\", array(\t\t\t\r\n\t\t\t':ID'=>$this->getIdusuario()\t\t\t\r\n\t\t));\r\n\r\n\t\t$this->setIdusuario(0);\r\n\t\t$this->setDeslogin(\"\");\r\n\t\t$this->setDessenha(\"\");\r\n\t\t$this->setDtcadastro(new DateTime());\r\n\r\n\r\n\t}\r\n\r\n\tpublic function __toString(){\r\n\r\n\t\treturn json_encode(array(\r\n\t\t\t\"idusuario\"=>$this->getIdusuario(),\r\n\t\t\t\"deslogin\"=>$this->getDeslogin(),\r\n\t\t\t\"dessenha\"=>$this->getDessenha(),\r\n\t\t\t\"dtcadastro\"=>$this->getDtcadastro()->format(\"d/m/Y H:i:s\")\r\n\r\n\t\t));\r\n\r\n\t}\r\n\r\n}\r\n\r\n?>",
        "implementation": [
          "path: class/Usuario.php",
          "GitHub: https://github.com/CanonEngineer/PHPDaoProject/blob/main/class/Usuario.php"
        ]
      }
