        "code": "from datetime import datetime\n\nfrom pydantic import BaseModel, Field\n\n\nclass InvoiceEmailResponse(BaseModel):\n    invoice_id: int\n    sent: bool\n    channel: str\n    recipient: str | None = None\n\n\nclass RemediationApprovalRequest(BaseModel):\n    playbook_slug: str\n    reason: str = \"\"\n    kind: str = \"remediation\"\n    payload: dict | None = None\n\n\nclass RemediationApprovalResponse(BaseModel):\n    id: int\n    playbook_slug: str\n    kind: str = \"remediation\"\n    payload: dict | None = None\n    status: str\n    requested_by: str | None\n    reason: str | None\n    created_at: datetime\n\n\nclass RemediationApprovePayload(BaseModel):\n    approved: bool = True\n    comment: str = \"\"\n\n\nclass CdnPurgeRequest(BaseModel):\n    paths: list[str] = Field(default_factory=lambda: [\"/*\"])\n    regions: list[str] | None = None\n\n\nclass CdnPurgeResponse(BaseModel):\n    purge_id: str\n    status: str\n    paths: list[str]\n    provider: str\n\n\nclass AuditorSsoStatusResponse(BaseModel):\n    enabled: bool\n    provider: str\n    login_url: str | None\n    issuer: str | None\n\n\nclass AuditorSsoLoginResponse(BaseModel):\n    redirect_url: str\n    state: str\n\n\nclass VisionStreamStatusResponse(BaseModel):\n    enabled: bool\n    ws_path: str\n    model: str\n",
