        "code": "from datetime import datetime\r\n\r\nfrom pydantic import BaseModel, Field\r\n\r\n\r\nclass ConsolidatedBillingResponse(BaseModel):\r\n    currency: str\r\n    total_mrr_cents: int\r\n    organizations: list[dict]\r\n    plans_breakdown: dict[str, int]\r\n\r\n\r\nclass CustomPlaybookCreate(BaseModel):\r\n    slug: str = Field(..., pattern=r\"^[a-z0-9-]+$\")\r\n    name: str\r\n    description: str = \"\"\r\n    yaml_content: str\r\n    enabled: bool = True\r\n\r\n\r\nclass CustomPlaybookResponse(BaseModel):\r\n    id: int\r\n    slug: str\r\n    name: str\r\n    description: str | None\r\n    enabled: bool\r\n    created_at: datetime\r\n\r\n\r\nclass CdnAnalyticsResponse(BaseModel):\r\n    hit_ratio_pct: float\r\n    requests_total: int\r\n    bandwidth_gb: float\r\n    regions: list[dict]\r\n    period_hours: int\r\n\r\n\r\nclass AuditorWhiteLabelResponse(BaseModel):\r\n    enabled: bool\r\n    brand_name: str\r\n    logo_url: str | None\r\n    primary_color: str\r\n    portal_title: str\r\n\r\n\r\nclass VisionOverlayResponse(BaseModel):\r\n    enabled: bool\r\n    overlays: list[dict]\r\n    map_layer: str\r\n",
