        "code": "from datetime import datetime\r\n\r\nfrom pydantic import BaseModel, Field\r\n\r\n\r\nclass CurrencyInfo(BaseModel):\r\n    code: str\r\n    symbol: str\r\n    rate_from_brl: float\r\n\r\n\r\nclass BillingCurrenciesResponse(BaseModel):\r\n    base_currency: str\r\n    supported: list[CurrencyInfo]\r\n    default_org_currency: str | None = None\r\n\r\n\r\nclass CurrencyConvertRequest(BaseModel):\r\n    amount_cents: int = Field(..., ge=0)\r\n    from_currency: str = \"BRL\"\r\n    to_currency: str = \"USD\"\r\n\r\n\r\nclass CurrencyConvertResponse(BaseModel):\r\n    amount_cents: int\r\n    from_currency: str\r\n    to_currency: str\r\n    converted_cents: int\r\n    rate: float\r\n    formatted: str\r\n\r\n\r\nclass PlaybookMarketplaceItem(BaseModel):\r\n    slug: str\r\n    name: str\r\n    description: str\r\n    category: str\r\n    author: str\r\n    installs: int\r\n    installed: bool = False\r\n\r\n\r\nclass PlaybookMarketplaceInstallRequest(BaseModel):\r\n    slug: str\r\n\r\n\r\nclass PlaybookMarketplaceInstallResponse(BaseModel):\r\n    slug: str\r\n    name: str\r\n    message: str\r\n\r\n\r\nclass ArOverlayMarker(BaseModel):\r\n    id: str\r\n    label: str\r\n    severity: str\r\n    type: str\r\n    node_id: str | None = None\r\n    x: float\r\n    y: float\r\n    z: float\r\n\r\n\r\nclass VisionArOverlayResponse(BaseModel):\r\n    enabled: bool\r\n    map_layer: str\r\n    markers: list[dict]\r\n    summary: str\r\n\r\n\r\nclass CdnCostRecommendation(BaseModel):\r\n    id: str\r\n    priority: str\r\n    title: str\r\n    detail: str\r\n    estimated_savings_pct: float\r\n\r\n\r\nclass CdnCostOptimizationResponse(BaseModel):\r\n    enabled: bool\r\n    period_hours: int\r\n    current_cost_usd: float\r\n    projected_savings_usd: float\r\n    recommendations: list[dict]\r\n    source: str\r\n\r\n\r\nclass AuditorTenantResponse(BaseModel):\r\n    id: int\r\n    org_id: int\r\n    org_name: str\r\n    slug: str\r\n    brand_name: str\r\n    is_active: bool\r\n    portal_url: str | None\r\n    created_at: datetime\r\n\r\n\r\nclass AuditorTenantCreateRequest(BaseModel):\r\n    org_id: int\r\n    slug: str = Field(..., pattern=r\"^[a-z0-9-]+$\")\r\n    brand_name: str = \"\"\r\n\r\n\r\nclass AuditorTenantSummaryResponse(BaseModel):\r\n    tenant_slug: str\r\n    org_name: str\r\n    brand_name: str\r\n    period_days: int\r\n    total_audit_events: int\r\n    failed_events: int\r\n    remediation_runs: int\r\n    controls_met: int\r\n    controls_total: int\r\n",
