        "file": "backend/app/schemas/phase21.py",
        "code": "from datetime import datetime\r\n\r\nfrom pydantic import BaseModel, Field\r\n\r\n\r\nclass RegionalTaxInfo(BaseModel):\r\n    region_code: str\r\n    region_name: str\r\n    tax_label: str\r\n    tax_rate_pct: float\r\n\r\n\r\nclass BillingTaxRegionsResponse(BaseModel):\r\n    enabled: bool\r\n    regions: list[RegionalTaxInfo]\r\n\r\n\r\nclass BillingTaxQuoteRequest(BaseModel):\r\n    amount_cents: int = Field(..., ge=0)\r\n    region_code: str = \"BR\"\r\n    currency: str = \"BRL\"\r\n\r\n\r\nclass BillingTaxQuoteResponse(BaseModel):\r\n    region_code: str\r\n    tax_label: str\r\n    tax_rate_pct: float\r\n    subtotal_cents: int\r\n    tax_cents: int\r\n    total_cents: int\r\n    currency: str\r\n    formatted_total: str\r\n\r\n\r\nclass PlaybookReviewCreate(BaseModel):\r\n    playbook_slug: str\r\n    rating: int = Field(..., ge=1, le=5)\r\n    comment: str = \"\"\r\n\r\n\r\nclass PlaybookReviewResponse(BaseModel):\r\n    id: int\r\n    playbook_slug: str\r\n    username: str\r\n    rating: int\r\n    comment: str | None\r\n    created_at: datetime\r\n\r\n\r\nclass PlaybookMarketplaceItemExtended(BaseModel):\r\n    slug: str\r\n    name: str\r\n    description: str\r\n    category: str\r\n    author: str\r\n    installs: int\r\n    installed: bool\r\n    avg_rating: float\r\n    review_count: int\r\n\r\n\r\nclass VisionWebXrResponse(BaseModel):\r\n    enabled: bool\r\n    supported: bool\r\n    ar_overlay_url: str\r\n    session_features: list[str]\r\n    mobile_hint: str\r\n\r\n\r\nclass CdnAutoPurgeResponse(BaseModel):\r\n    enabled: bool\r\n    purge_id: str\r\n    paths: list[str]\r\n    reason: str\r\n    estimated_savings_usd: float\r\n    provider: str\r\n\r\n\r\nclass AuditorTenantBillingRow(BaseModel):\r\n    tenant_slug: str\r\n    org_name: str\r\n    brand_name: str\r\n    monthly_fee_cents: int\r\n    currency: str\r\n    formatted_fee: str\r\n    status: str\r\n\r\n\r\nclass AuditorTenantBillingResponse(BaseModel):\r\n    enabled: bool\r\n    currency: str\r\n    total_mrr_cents: int\r\n    tenants: list[dict]\r\n",
