        "file": "backend/app/schemas/phase4.py",
        "code": "from datetime import datetime\n\nfrom pydantic import BaseModel, Field\n\nfrom app.models import AlertStatus, EventSeverity, UserRole\n\n\nclass AlertResponse(BaseModel):\n    id: int\n    event_id: int\n    channel: str\n    status: AlertStatus\n    sent_at: datetime | None\n    error_message: str | None\n    created_at: datetime\n\n    model_config = {\"from_attributes\": True}\n\n\nclass AlertSilenceCreate(BaseModel):\n    minutes: int = Field(default=60, ge=1, le=43200)\n    reason: str | None = None\n\n\nclass AlertSilenceResponse(BaseModel):\n    id: int\n    event_type: str\n    device_id: int | None\n    reason: str | None\n    created_by: str | None\n    silenced_until: datetime\n    created_at: datetime\n\n    model_config = {\"from_attributes\": True}\n\n\nclass AlertConfigResponse(BaseModel):\n    enabled_channels: list[str]\n    telegram_configured: bool\n    discord_configured: bool\n    slack_configured: bool\n    teams_configured: bool\n    email_configured: bool\n    sms_configured: bool\n    push_configured: bool\n    webhook_configured: bool\n    ldap_enabled: bool\n    channel_configs: list[\"AlertChannelConfigResponse\"] = Field(default_factory=list)\n\n\nclass AlertChannelConfigBase(BaseModel):\n    channel: str\n    name: str\n    is_enabled: bool = True\n    destinations: list[str] = Field(default_factory=list)\n    config: dict = Field(default_factory=dict)\n\n\nclass AlertChannelConfigCreate(AlertChannelConfigBase):\n    org_id: int | None = None\n\n\nclass AlertChannelConfigUpdate(BaseModel):\n    name: str | None = None\n    is_enabled: bool | None = None\n    destinations: list[str] | None = None\n    config: dict | None = None\n\n\nclass AlertChannelTestRequest(BaseModel):\n    subject: str = \"Teste SentinelAI\"\n    body: str = \"Mensagem de teste enviada pela Fase 2.\"\n    destination: str | None = None\n\n\nclass AlertChannelConfigResponse(AlertChannelConfigBase):\n    id: int\n    org_id: int | None\n    last_test_status: str | None = None\n    last_test_message: str | None = None\n    last_tested_at: datetime | None = None\n    created_at: datetime\n    updated_at: datetime | None = None\n\n    model_config = {\"from_attributes\": True}\n\n\nclass MaintenanceWindowCreate(BaseModel):\n    name: str\n    description: str | None = None\n    starts_at: datetime\n    ends_at: datetime\n\n\nclass MaintenanceWindowResponse(BaseModel):\n    id: int\n    name: str\n    description: str | None\n    starts_at: datetime\n    ends_at: datetime\n    is_active: bool\n    created_at: datetime\n\n    model_config = {\"from_attributes\": True}\n\n\nclass AnomalyResponse(BaseModel):\n    id: int\n    device_id: int\n    metric_name: str\n    expected_value: float | None\n    actual_value: float\n    severity: EventSeverity\n    message: str\n    is_resolved: bool\n    detected_at: datetime\n\n    model_config = {\"from_attributes\": True}\n\n\nclass ReportJobCreate(BaseModel):\n    report_type: str = Field(description=\"devices | events | summary | sla\")\n    format: str = Field(description=\"xlsx | pdf\")\n    days: int = 7\n    site_id: int | None = None\n\n\nclass ReportJobResponse(BaseModel):\n    id: int\n    report_type: str\n    format: str\n    status: str\n    file_path: str | None\n    summary: str | None\n    error_message: str | None\n    params: dict | None = None\n    created_at: datetime\n    completed_at: datetime | None\n\n    model_config = {\"from_attributes\": True}\n\n\nclass UserCreate(BaseModel):\n    username: str\n    password: str\n    role: UserRole = UserRole.VIEWER\n\n\nclass UserUpdate(BaseModel):\n    role: UserRole | None = None\n    is_active: bool | None = None\n\n\nclass UserAdminResponse(BaseModel):\n    id: int\n    username: str\n    role: UserRole\n    is_ldap: bool\n    is_active: bool\n    created_at: datetime\n\n    model_config = {\"from_attributes\": True}\n",
