        "file": "backend/scripts/smoke_phase20.py",
        "code": "#!/usr/bin/env python3\r\n\"\"\"Smoke test Fase 20 endpoints.\"\"\"\r\n\r\nimport json\r\nimport sys\r\nimport time\r\nimport urllib.error\r\nimport urllib.parse\r\nimport urllib.request\r\n\r\nBASE = \"http://127.0.0.1:8000\"\r\n\r\n\r\ndef req(method: str, path: str, token: str | None = None, data: dict | None = None) -> tuple[int, object]:\r\n    headers = {\"Content-Type\": \"application/json\"}\r\n    if token:\r\n        headers[\"Authorization\"] = f\"Bearer {token}\"\r\n    body = json.dumps(data).encode() if data is not None else None\r\n    request = urllib.request.Request(BASE + path, data=body, headers=headers, method=method)\r\n    try:\r\n        with urllib.request.urlopen(request, timeout=15) as resp:\r\n            raw = resp.read().decode()\r\n            return resp.status, json.loads(raw) if raw else {}\r\n    except urllib.error.HTTPError as exc:\r\n        return exc.code, exc.read().decode()\r\n\r\n\r\ndef req_form(path: str, form: dict[str, str]) -> tuple[int, object]:\r\n    body = urllib.parse.urlencode(form).encode()\r\n    request = urllib.request.Request(\r\n        BASE + path,\r\n        data=body,\r\n        headers={\"Content-Type\": \"application/x-www-form-urlencoded\"},\r\n        method=\"POST\",\r\n    )\r\n    try:\r\n        with urllib.request.urlopen(request, timeout=15) as resp:\r\n            raw = resp.read().decode()\r\n            return resp.status, json.loads(raw) if raw else {}\r\n    except urllib.error.HTTPError as exc:\r\n        return exc.code, exc.read().decode()\r\n\r\n\r\ndef main() -> int:\r\n    for _ in range(20):\r\n        try:\r\n            status, _ = req(\"GET\", \"/health\")\r\n            if status == 200:\r\n                break\r\n        except Exception:\r\n            pass\r\n        time.sleep(1)\r\n    else:\r\n        print(\"FAIL API not ready\")\r\n        return 1\r\n\r\n    status, login = req_form(\"/api/auth/login\", {\"username\": \"admin\", \"password\": \"admin123\"})\r\n    if status != 200:\r\n        print(\"FAIL login\", status, login)\r\n        return 1\r\n    token = login[\"access_token\"]\r\n\r\n    _, system = req(\"GET\", \"/api/system/status\", token)\r\n    print(f\"VERSION {system.get('version') if isinstance(system, dict) else system}\")\r\n\r\n    checks: list[tuple[str, bool, int, object]] = []\r\n\r\n    def check(name: str, method: str, path: str, data: dict | None = None, expect: int = 200) -> None:\r\n        st, body = req(method, path, token, data)\r\n        ok = st == expect\r\n        checks.append((name, ok, st, body))\r\n        print(f\"{'PASS' if ok else 'FAIL'} {name} -> {st}\")\r\n\r\n    check(\"billing/currencies\", \"GET\", \"/api/billing/currencies\")\r\n    check(\"billing/convert\", \"POST\", \"/api/billing/convert\", {\"amount_cents\": 9900, \"from_currency\": \"BRL\", \"to_currency\": \"USD\"})\r\n    check(\"billing/plans/USD\", \"GET\", \"/api/billing/plans/USD\")\r\n    check(\"playbook marketplace\", \"GET\", \"/api/scale/playbooks/marketplace\")\r\n    check(\"vision ar-overlay\", \"GET\", \"/api/vision/ar-overlay?map_layer=physical\")\r\n    check(\"cdn cost-optimization\", \"GET\", \"/api/cdn/cost-optimization?period_hours=24\")\r\n    check(\"auditor tenants\", \"GET\", \"/api/auditor/tenants\")\r\n\r\n    st, mp = req(\"GET\", \"/api/scale/playbooks/marketplace\", token)\r\n    if st == 200 and isinstance(mp, list):\r\n        slug = next((p[\"slug\"] for p in mp if not p.get(\"installed\")), None)\r\n        if slug:\r\n            check(\"playbook install\", \"POST\", \"/api/scale/playbooks/marketplace/install\", {\"slug\": slug})\r\n        else:\r\n            print(\"SKIP playbook install (all installed)\")\r\n\r\n    failed = [c for c in checks if not c[1]]\r\n    print(\"---\")\r\n    print(f\"Results: {len(checks) - len(failed)}/{len(checks)} passed\")\r\n    for name, _ok, st, body in failed:\r\n        print(\"FAIL detail\", name, st, body)\r\n    return 0 if not failed else 1\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    sys.exit(main())\r\n",
        "implementation": [
          "path: backend/scripts/smoke_phase20.py",
          "GitHub: https://github.com/CanonEngineer/SentinelAI/blob/main/backend/scripts/smoke_phase20.py"
        ]
