        "file": "docs/feature-inventory.json",
        "code": "{\n  \"version\": \"2026-07-28b\",\n  \"project\": \"SentinelAI\",\n  \"baseline_doc\": \"docs/PHASE-0-BASELINE.md\",\n  \"sections\": {\n    \"map_editor\": {\n      \"title\": \"Map Editor (The Dude++)\",\n      \"items\": [\n        { \"id\": \"infinite_canvas\", \"label\": \"Canvas infinito (Infinite Canvas)\", \"status\": \"done\", \"notes\": \"React Flow pan livre — TopologyMap.tsx\" },\n        { \"id\": \"zoom\", \"label\": \"Zoom fluido 10%–500%\", \"status\": \"done\", \"notes\": \"minZoom 0.1, maxZoom 5\" },\n        { \"id\": \"drag_drop_library\", \"label\": \"Drag-and-drop da biblioteca de equipamentos\", \"status\": \"done\", \"notes\": \"DeviceLibrary.tsx\" },\n        { \"id\": \"smart_connectors\", \"label\": \"Conectores inteligentes (anti-cruzamento)\", \"status\": \"done\", \"notes\": \"Auto-layout dagre + ELK\" },\n        { \"id\": \"grouping\", \"label\": \"Agrupamento racks, salas, prédios, VLANs, sites\", \"status\": \"done\", \"notes\": \"GroupType: rack, room, building, vlan, site, department\" },\n        { \"id\": \"snap_grid\", \"label\": \"Grade magnética (Snap to Grid)\", \"status\": \"done\", \"notes\": \"Grade 20px, toggle na toolbar\" },\n        { \"id\": \"alignment_guides\", \"label\": \"Guias de alinhamento inteligentes\", \"status\": \"done\", \"notes\": \"AlignmentGuides.tsx\" },\n        { \"id\": \"undo_redo\", \"label\": \"Desfazer/Refazer ilimitado\", \"status\": \"done\", \"notes\": \"Histórico ilimitado em TopologyMap + useMapHistory.ts\" },\n        { \"id\": \"minimap\", \"label\": \"Minimap para navegação\", \"status\": \"done\", \"notes\": \"React Flow MiniMap\" },\n        { \"id\": \"edge_styles\", \"label\": \"Estilos de conexão (reta, ortogonal, curva)\", \"status\": \"done\", \"notes\": \"straight, step, smoothstep, default\" },\n        { \"id\": \"layers\", \"label\": \"Camadas (lógica, física, elétrica, Wi-Fi)\", \"status\": \"done\", \"notes\": \"Filtro map_layer na toolbar\" },\n        { \"id\": \"export\", \"label\": \"Exportação PNG, SVG, PDF, Visio\", \"status\": \"done\", \"notes\": \"PNG/SVG client; PDF/VSDX server\" },\n        { \"id\": \"realtime_collab\", \"label\": \"Colaboração em tempo real (multi-admin)\", \"status\": \"done\", \"notes\": \"WebSocket /ws/map\" },\n        { \"id\": \"auto_update_inventory\", \"label\": \"Atualização automática após inventário\", \"status\": \"done\", \"notes\": \"Poll discovery jobs 5s + SSE inventory_completed + reload mapa\" },\n        { \"id\": \"view_2d_3d\", \"label\": \"Visualização 2D e 3D\", \"status\": \"done\", \"notes\": \"TopologyMap + Map3DView.tsx\" },\n        { \"id\": \"traffic_animation\", \"label\": \"Animações de tráfego nos links\", \"status\": \"done\", \"notes\": \"SNMP quando há match de porta; senão Mbps simulado + linha contínua/partícula (UX clássica)\" },\n        { \"id\": \"dynamic_filters\", \"label\": \"Filtros dinâmicos\", \"status\": \"done\", \"notes\": \"Tipo, status, tag + filtro VLAN na toolbar (vlan_id API)\" },\n        { \"id\": \"tags\", \"label\": \"Sistema de etiquetas (Tags)\", \"status\": \"done\", \"notes\": \"JSONB tags + filtro API\" }\n      ]\n    },\n    \"nms_platform\": {\n      \"title\": \"Plataforma NMS\",\n      \"items\": [\n        { \"id\": \"discovery_icmp\", \"label\": \"Descoberta automática — ICMP\", \"status\": \"done\", \"notes\": \"subnet_scanner.py, ping pós-nmap, scan /24 — baseline 603/603 ping\" },\n        { \"id\": \"discovery_snmp\", \"label\": \"Descoberta automática — SNMP\", \"status\": \"partial\", \"notes\": \"Código + multi-community + credenciais/SNMPv3 (Fase 2–4); cobertura de frota depende de communities/credenciais no lab\" },\n        { \"id\": \"discovery_ssh\", \"label\": \"Descoberta automática — SSH\", \"status\": \"done\", \"notes\": \"ssh_collector.py + toggle use_ssh no scan\" },\n        { \"id\": \"discovery_wmi\", \"label\": \"Descoberta automática — WMI\", \"status\": \"partial\", \"notes\": \"WMI ok (CPU/RAM/disk); temp ausente em VMs QEMU (WBEM_E_NOT_SUPPORTED)\" },\n        { \"id\": \"dynamic_topology\", \"label\": \"Mapeamento dinâmico da topologia\", \"status\": \"done\", \"notes\": \"LLDP/CDP, auto-cadastro, job horário Celery\" },\n        { \"id\": \"interactive_diagrams\", \"label\": \"Diagramas interativos da infraestrutura\", \"status\": \"done\", \"notes\": \"TopologyMap 2D/3D editável\" },\n        { \"id\": \"realtime_monitoring\", \"label\": \"Monitoramento em tempo real\", \"status\": \"done\", \"notes\": \"SSE + Redis pub/sub (realtime_events) — Fase 1.4\" },\n        { \"id\": \"hw_inventory\", \"label\": \"Inventário de hardware\", \"status\": \"done\", \"notes\": \"GET /api/devices/{id}/hardware + aba Hardware (serial, ports, SNMP)\" },\n        { \"id\": \"sw_inventory\", \"label\": \"Inventário de software\", \"status\": \"done\", \"notes\": \"software_collector.py SNMP hrSW + WMI, GET/POST /api/devices/{id}/software\" },\n        { \"id\": \"alerts_email\", \"label\": \"Alertas por e-mail\", \"status\": \"partial\", \"notes\": \"Código email.py; SMTP não configurado no baseline (smtp_host vazio)\" },\n        { \"id\": \"alerts_sms\", \"label\": \"Alertas por SMS\", \"status\": \"partial\", \"notes\": \"Twilio REST; credenciais vazias no baseline\" },\n        { \"id\": \"alerts_apps\", \"label\": \"Alertas por aplicativos\", \"status\": \"partial\", \"notes\": \"Telegram/Slack/Discord/Teams/Webhook código ok; webhooks vazias; regras/channels UI ok\" },\n        { \"id\": \"alerts_silence\", \"label\": \"Silence / snooze por fingerprint\", \"status\": \"done\", \"notes\": \"AlertSilence + POST /api/alerts/{id}/silence · UI Alerts\" },\n        { \"id\": \"alerts_dedupe\", \"label\": \"Dedupe temporal (event_type+device)\", \"status\": \"done\", \"notes\": \"ALERT_SUPPRESS_REPEAT_MINUTES wired in rule_engine\" },\n        { \"id\": \"alerts_enrichment\", \"label\": \"Enrichment hostname/IP/site no payload\", \"status\": \"done\", \"notes\": \"build_enriched_payload no process_pending_alerts\" },\n        { \"id\": \"custom_dashboards\", \"label\": \"Dashboards personalizáveis\", \"status\": \"done\", \"notes\": \"useDashboardLayout — show/hide/reorder widgets + localStorage\" },\n        { \"id\": \"device_monitoring\", \"label\": \"Monitor servers/switches/routers/firewalls/printers/APs\", \"status\": \"partial\", \"notes\": \"Tipos + plugins ok; métricas profundas só ~3 hosts (cpu/mem/disk)\" },\n        { \"id\": \"vm_cloud_monitoring\", \"label\": \"Monitor VMs e ambientes nuvem\", \"status\": \"done\", \"notes\": \"Plugins Proxmox/VMware/AWS/Azure + sync Celery → Device VM\" },\n        { \"id\": \"performance_history\", \"label\": \"Histórico de desempenho e relatórios\", \"status\": \"partial\", \"notes\": \"metrics/SLA/PDF ok; histórico quase só latency/packet_loss\" },\n        { \"id\": \"integration_apis\", \"label\": \"APIs para integração\", \"status\": \"done\", \"notes\": \"REST FastAPI /docs, Zabbix/PRTG export, webhooks\" }\n      ]\n    },\n    \"stabilization\": {\n      \"title\": \"Estabilização operacional (Fase 0+)\",\n      \"items\": [\n        { \"id\": \"ops.sse_redis\", \"label\": \"SSE via Redis pub/sub (API ↔ workers)\", \"status\": \"done\", \"notes\": \"realtime_events.py Redis channel + history — Fase 1.4\" },\n        { \"id\": \"ops.health_deep\", \"label\": \"Health real DB+Redis(+Celery)\", \"status\": \"done\", \"notes\": \"/health checks postgres/redis/celery; 503 se critical — Fase 1.2\" },\n        { \"id\": \"ops.compose_prod\", \"label\": \"Compose prod sem --reload\", \"status\": \"done\", \"notes\": \"default sem reload; docker-compose.dev.yml com --reload — Fase 1.1\" },\n        { \"id\": \"ops.auth_harden\", \"label\": \"Hardening auth (ad\n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
