        "code": "import { useEffect, useState } from \"react\";\nimport { clearToken, fetchMe, getToken } from \"./api/client\";\nimport AppShell, { type AppPage } from \"./components/layout/AppShell\";\nimport { ErrorBoundary } from \"./components/ErrorBoundary\";\nimport { ThemeProvider } from \"./context/ThemeProvider\";\nimport { AuthProvider } from \"./context/AuthContext\";\nimport ChangePasswordPage from \"./pages/ChangePasswordPage\";\nimport Dashboard from \"./pages/Dashboard\";\nimport LoginPage from \"./pages/LoginPage\";\nimport ScannerPage from \"./pages/ScannerPage\";\nimport TopologyMap from \"./pages/TopologyMap\";\nimport AlertsPage from \"./pages/AlertsPage\";\nimport ReportsPage from \"./pages/ReportsPage\";\nimport InfrastructurePage from \"./pages/InfrastructurePage\";\nimport NocCopilotPage from \"./pages/NocCopilotPage\";\nimport ChatbotPage from \"./pages/ChatbotPage\";\nimport PlatformPage from \"./pages/PlatformPage\";\nimport UsersPage from \"./pages/UsersPage\";\nimport ZionPage from \"./pages/ZionPage\";\nimport WallboardPage from \"./pages/WallboardPage\";\nimport PublicWallboardPage, { isPublicWallboardRoute } from \"./pages/PublicWallboardPage\";\n\nexport default function App() {\n  const [page, setPage] = useState<AppPage>(\"dashboard\");\n  const [authenticated, setAuthenticated] = useState(Boolean(getToken()));\n  const [mustChangePassword, setMustChangePassword] = useState(false);\n  const [booting, setBooting] = useState(Boolean(getToken()));\n  const [publicWallboard, setPublicWallboard] = useState(isPublicWallboardRoute());\n\n  useEffect(() => {\n    const onHash = () => setPublicWallboard(isPublicWallboardRoute());\n    window.addEventListener(\"hashchange\", onHash);\n    return () => window.removeEventListener(\"hashchange\", onHash);\n  }, []);\n\n  useEffect(() => {\n    if (publicWallboard) {\n      setBooting(false);\n      return;\n    }\n    if (!getToken()) {\n      setBooting(false);\n      return;\n    }\n    fetchMe()\n      .then((me) => {\n        setAuthenticated(true);\n        setMustChangePassword(Boolean(me.must_change_password));\n      })\n      .catch(() => {\n        clearToken();\n        setAuthenticated(false);\n        setMustChangePassword(false);\n      })\n      .finally(() => setBooting(false));\n  }, [publicWallboard]);\n\n  if (publicWallboard) {\n    return (\n      <ThemeProvider>\n        <ErrorBoundary>\n          <PublicWallboardPage />\n        </ErrorBoundary>\n      </ThemeProvider>\n    );\n  }\n\n  if (booting) {\n    return (\n      <ThemeProvider>\n        <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"center\", gap: \"0.75rem\", padding: \"3rem\" }}>\n          <span className=\"sa-spinner\" />\n          <span style={{ color: \"var(--sa-text-muted)\" }}>A verificar sessão...</span>\n        </div>\n      </ThemeProvider>\n    );\n  }\n\n  if (!authenticated) {\n    return (\n      <ThemeProvider>\n        <ErrorBoundary>\n          <LoginPage\n            onLogin={(opts) => {\n              setAuthenticated(true);\n              setMustChangePassword(Boolean(opts?.must_change_password));\n            }}\n          />\n        </ErrorBoundary>\n      </ThemeProvider>\n    );\n  }\n\n  if (mustChangePassword) {\n    return (\n      <ThemeProvider>\n        <ErrorBoundary>\n          <ChangePasswordPage onDone={() => setMustChangePassword(false)} />\n        </ErrorBoundary>\n      </ThemeProvider>\n    );\n  }\n\n  return (\n    <ThemeProvider>\n      <AuthProvider>\n        <ErrorBoundary>\n        <AppShell\n          page={page}\n          onNavigate={setPage}\n          onLogout={() => {\n            clearToken();\n            setAuthenticated(false);\n            setMustChangePassword(false);\n          }}\n        >\n          <ErrorBoundary key={page}>\n            {page === \"dashboard\" && <Dashboard />}\n            {page === \"topology\" && <TopologyMap />}\n            {page === \"scanner\" && <ScannerPage />}\n            {page === \"reports\" && <ReportsPage />}\n            {page === \"copilot\" && <NocCopilotPage />}\n            {page === \"chatbot\" && <ChatbotPage />}\n            {page === \"alerts\" && <AlertsPage />}\n            {page === \"infra\" && <InfrastructurePage />}\n            {page === \"platform\" && <PlatformPage />}\n            {page === \"users\" && <UsersPage />}\n            {page === \"zion\" && <ZionPage />}\n            {page === \"wallboard\" && <WallboardPage />}\n          </ErrorBoundary>\n        </AppShell>\n        </ErrorBoundary>\n      </AuthProvider>\n    </ThemeProvider>\n  );\n}\n",
        "implementation": [
          "path: frontend/src/App.tsx",
          "GitHub: https://github.com/CanonEngineer/SentinelAI/blob/main/frontend/src/App.tsx"
        ]
