        "code": "import { useCallback } from \"react\";\r\nimport { Panel, useReactFlow } from \"@xyflow/react\";\r\nimport { Maximize2, Minus, Plus } from \"lucide-react\";\r\n\r\nexport default function FlowControls() {\r\n  const { zoomIn, zoomOut, fitView } = useReactFlow();\r\n\r\n  const handleFit = useCallback(() => {\r\n    fitView({ padding: 0.35, maxZoom: 1, duration: 300 });\r\n  }, [fitView]);\r\n\r\n  return (\r\n    <Panel position=\"bottom-left\" className=\"sa-flow-controls-panel\">\r\n      <div className=\"sa-flow-controls-custom\">\r\n        <button type=\"button\" title=\"Aumentar zoom\" aria-label=\"Aumentar zoom\" onClick={() => zoomIn({ duration: 200 })}>\r\n          <Plus size={16} />\r\n        </button>\r\n        <button type=\"button\" title=\"Diminuir zoom\" aria-label=\"Diminuir zoom\" onClick={() => zoomOut({ duration: 200 })}>\r\n          <Minus size={16} />\r\n        </button>\r\n        <button type=\"button\" title=\"Ajustar visão\" aria-label=\"Ajustar visão\" onClick={handleFit}>\r\n          <Maximize2 size={15} />\r\n        </button>\r\n      </div>\r\n    </Panel>\r\n  );\r\n}\r\n",
