        "file": "frontend/src/components/ui/StatusBadge.tsx",
        "code": "const map: Record<string, string> = {\r\n  active: \"sa-badge-success\",\r\n  inactive: \"sa-badge-danger\",\r\n  unknown: \"sa-badge-warning\",\r\n  retired: \"sa-badge-neutral\",\r\n  pending: \"sa-badge-warning\",\r\n  running: \"sa-badge-info\",\r\n  completed: \"sa-badge-success\",\r\n  failed: \"sa-badge-danger\",\r\n  sent: \"sa-badge-success\",\r\n  critical: \"sa-badge-danger\",\r\n  warning: \"sa-badge-warning\",\r\n  info: \"sa-badge-info\",\r\n};\r\n\r\nconst labels: Record<string, string> = {\r\n  active: \"Online\",\r\n  inactive: \"Offline\",\r\n  unknown: \"Desconhecido\",\r\n  retired: \"Aposentado\",\r\n  pending: \"Pendente\",\r\n  running: \"Executando\",\r\n  completed: \"Concluído\",\r\n  failed: \"Falhou\",\r\n  sent: \"Enviado\",\r\n  critical: \"Crítico\",\r\n  warning: \"Aviso\",\r\n  info: \"Info\",\r\n};\r\n\r\nexport default function StatusBadge({ status }: { status: string }) {\r\n  return (\r\n    <span className={`sa-badge ${map[status] ?? \"sa-badge-neutral\"}`}>\r\n      {labels[status] ?? status}\r\n    </span>\r\n  );\r\n}\r\n",
