        "file": "frontend/src/pages/ZionPage.tsx",
        "code": "import { useCallback, useEffect, useMemo, useRef, useState } from \"react\";\r\nimport {\r\n  Activity,\r\n  AlertTriangle,\r\n  Bot,\r\n  CheckCircle2,\r\n  Cpu,\r\n  FileBarChart,\r\n  Gauge,\r\n  HardDrive,\r\n  Hexagon,\r\n  Map,\r\n  Network,\r\n  Radar,\r\n  RefreshCw,\r\n  Server,\r\n  Shield,\r\n  Sparkles,\r\n  Thermometer,\r\n  Trash2,\r\n  Workflow,\r\n  X,\r\n} from \"lucide-react\";\r\nimport {\r\n  applyZionTemplates,\r\n  copilotChat,\r\n  createZionPanel,\r\n  deleteZionPanel,\r\n  removeZionPanelCard,\r\n  addMetricsToZionPanel,\r\n  fetchAlertConfig,\r\n  fetchAlerts,\r\n  fetchAuditLogs,\r\n  fetchDiscoveryJobs,\r\n  fetchEvents,\r\n  fetchRemediationPlaybooks,\r\n  fetchZionCapabilities,\r\n  fetchZionInventory,\r\n  fetchZionOverview,\r\n  fetchZionPanelMeta,\r\n  fetchZionPanels,\r\n  fetchZionTemplates,\r\n  pollZionDevice,\r\n  startDiscovery,\r\n  type AlertConfig,\r\n  type AuditLogEntry,\r\n  type DiscoveryJob,\r\n  type Event,\r\n  type RemediationPlaybook,\r\n  type ZionCapability,\r\n  type ZionCorporateAsset,\r\n  type ZionOverview,\r\n  type ZionPanel,\r\n  type ZionPanelMeta,\r\n  type ZionTemplate,\r\n  type ZionTemplateApplyDetail,\r\n} from \"../api/client\";\r\nimport DataTable, { type Column } from \"../components/ui/DataTable\";\r\nimport DeviceMetricsTab from \"../components/DeviceMetricsTab\";\r\nimport StatCard from \"../components/ui/StatCard\";\r\nimport StatusBadge from \"../components/ui/StatusBadge\";\r\nimport ZionPane from \"../components/ZionPane\";\r\nimport { useAuth } from \"../context/AuthContext\";\r\n\r\ntype ZionTab =\r\n  | \"overview\"\r\n  | \"discovery\"\r\n  | \"inventory\"\r\n  | \"templates\"\r\n  | \"monitoring\"\r\n  | \"map\"\r\n  | \"events\"\r\n  | \"history\"\r\n  | \"ai\"\r\n  | \"alerts\"\r\n  | \"protocols\"\r\n  | \"reports\"\r\n  | \"audit\"\r\n  | \"automation\"\r\n  | \"capabilities\";\r\n\r\nconst TABS: { id: ZionTab; label: string }[] = [\r\n  { id: \"overview\", label: \"Dashboard\" },\r\n  { id: \"discovery\", label: \"Descoberta\" },\r\n  { id: \"inventory\", label: \"Inventário\" },\r\n  { id: \"templates\", label: \"Templates\" },\r\n  { id: \"monitoring\", label: \"Monitoramento\" },\r\n  { id: \"map\", label: \"Mapa\" },\r\n  { id: \"events\", label: \"Eventos\" },\r\n  { id: \"history\", label: \"Histórico\" },\r\n  { id: \"ai\", label: \"IA\" },\r\n  { id: \"alerts\", label: \"Alertas\" },\r\n  { id: \"protocols\", label: \"Protocolos\" },\r\n  { id: \"reports\", label: \"Relatórios\" },\r\n  { id: \"audit\", label: \"Auditoria\" },\r\n  { id: \"automation\", label: \"Automação\" },\r\n  { id: \"capabilities\", label: \"Cobertura\" },\r\n];\r\n\r\nconst PROTOCOL_MATRIX: { name: string; status: \"ready\" | \"partial\" | \"planned\"; note: string }[] = [\r\n  { name: \"ICMP\", status: \"ready\", note: \"Ping monitors + discovery\" },\r\n  { name: \"SNMP v1/v2\", status: \"ready\", note: \"CPU, mem, disco, temperatura, traps\" },\r\n  { name: \"SNMP v3\", status: \"partial\", note: \"Estrutura pronta; auth SNMPv3 em evolução\" },\r\n  { name: \"WMI\", status: \"ready\", note: \"OS, serial, AD, usuário, mem/disco/temp\" },\r\n  { name: \"WinRM\", status: \"ready\", note: \"Probe /wsman 5985/5986\" },\r\n  { name: \"SSH\", status: \"ready\", note: \"ssh_collector + config backup\" },\r\n  { name: \"Telnet\", status: \"ready\", note: \"Probe porta 23 + banner\" },\r\n  { name: \"HTTP/HTTPS\", status: \"ready\", note: \"Monitores HTTP/HTTPS\" },\r\n  { name: \"TCP\", status: \"ready\", note: \"Monitor TCP\" },\r\n  { name: \"UDP\", status: \"partial\", note: \"Scan UDP nmap opcional\" },\r\n  { name: \"LDAP\", status: \"ready\", note: \"Auth + sync displayName/OU\" },\r\n  { name: \"DNS\", status: \"ready\", note: \"PTR/RDAP + DNS via WMI\" },\r\n  { name: \"NTP\", status: \"ready\", note: \"Probe UDP 123\" },\r\n  { name: \"Modbus TCP\", status: \"ready\", note: \"Probe porta 502 (FC3)\" },\r\n  { name: \"MQTT\", status: \"ready\", note: \"CONNECT/CONNACK porta 1883\" },\r\n  { name: \"IPMI\", status: \"ready\", note: \"RMCP ping UDP 623\" },\r\n  { name: \"SMB / FTP / SFTP\", status: \"planned\", note: \"Via templates/automação\" },\r\n  { name: \"REST API\", status: \"ready\", note: \"FastAPI + plugins\" },\r\n];\r\n\r\nfunction statusLabel(status: string) {\r\n  if (status === \"ready\" || status === \"done\") return \"Pronto\";\r\n  if (status === \"partial\") return \"Parcial\";\r\n  return \"Planejado\";\r\n}\r\n\r\nconst INDICATOR_EMOJI: Record<string, string> = {\r\n  cpu_temp: \"🌡️\",\r\n  disk: \"💾\",\r\n  memory: \"🧠\",\r\n  cpu: \"⚙️\",\r\n  interfaces: \"🌐\",\r\n  traffic: \"📈\",\r\n  ups: \"🔋\",\r\n  os: \"🖥️\",\r\n  uptime: \"⏱️\",\r\n  services: \"🔄\",\r\n  filesystems: \"📂\",\r\n  history: \"📊\",\r\n  triggers: \"🚨\",\r\n  events: \"📜\",\r\n  inventory: \"📋\",\r\n  discovery: \"🔍\",\r\n  protocols: \"📡\",\r\n  assets: \"🖥️\",\r\n};\r\n\r\nfunction indicatorVariant(status: string): \"blue\" | \"green\" | \"red\" | \"amber\" {\r\n  if (status === \"critical\") return \"red\";\r\n  if (status === \"warning\") return \"amber\";\r\n  if (status === \"empty\") return \"blue\";\r\n  return \"green\";\r\n}\r\n\r\nexport default function ZionPage() {\r\n  const { canWrite } = useAuth();\r\n  const [tab, setTab] = useState<ZionTab>(\"overview\");\r\n  const [overview, setOverview] = useState<ZionOverview | null>(null);\r\n  const [inventory, setInventory] = useState<ZionCorporateAsset[]>([]);\r\n  const [templates, setTemplates] = useState<ZionTemplate[]>([]);\r\n  const [capabilities, setCapabilities] = useState<{ modules: ZionCapability[]; reuse_pct: number; message: string } | null>(null);\r\n  const [jobs, setJobs] = useState<DiscoveryJob[]>([]);\r\n  const [events, setEvents] = useState<Event[]>([]);\r\n  const [alertConfig, setAlertConfig] = useState<AlertConfig | null>(null);\r\n  const [alertsCount, setAlertsCount] = useState(0);\r\n  const [audit, setAudit] = useState<AuditLogEntry[]>([]);\r\n  const [playbooks, setPlaybooks] = useState<RemediationPlaybook[]>([]);\r\n  const [subnet, setSubnet] = useState(\"192.168.1.0/24\");\r\n  const [snmpCommunities, setSnmpCommunities] = useState(\"public,private\");\r\n  const [aiQuestion, setAiQuestion] = useState(\"Quais riscos críticos na rede agora?\");\r\n  const [aiAnswer, setAiAnswer] = useState<string | null>(null);\r\n  const [message, setMessage] = useState<string | null>(null);\r\n  const [toastVisible, setToastVisible] = useState(false);\r\n  const [toastLeaving, setToastLeaving] = useState(false);\r\n  const toastEpochRef = useRef(0);\r\n  const [loading, setLoading] = useState(true);\r\n  const [busy, setBusy] = useState(false);\r\n  const [panels, setPanels] = useState<ZionPanel[]>([]);\r\n  const [panelMeta, setPanelMeta] = useState<ZionPanelMeta | null>(null);\r\n  const [panelName, setPanelName] = useState(\"Temperatura dos servidores\");\r\n  const [panelCategory, setPanelCategory] = useState(\"cpu_temp\");\r\n  const [panelIps, setPanelIps] = useState(\"\");\r\n  const [panelAssetType, setPanelAssetType] = useState(\"server\");\r\n  const [panelFilter, setPanelFilter] = useState(\"\");\r\n  const [panelThreshold, setPanelThreshold] = useState(\"85\");\r\n  const [addMetricByPanel, setAddMetricByPanel] = useState<Record<number, string>>({});\r\n  const [inventoryMetricsOnly, setInventoryMetricsOnly] = useState(false);\r\n  const [hideEmptyCards, setHideEmptyCards] = useState(false);\r\n  const [historyDeviceId, setHistoryDeviceId] = useState<number | \"\">(\"\");\r\n  const [tplWizard, setTplWizard] = useState<null | {\r\n    template: ZionTemplate;\r\n    ipFilter: string;\r\n    selectedIds: number\n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
